<script setup lang="ts">
import {computed,ref} from 'vue'
import {useDb} from '../../../stores/db'
import {useSession} from '../../../stores/session'
import {StatusBadge,PreviewBanner} from '../../../components/shared'
import {businessHoursBetween} from '../../../lib/businessTime'
import {addLegalMilestone} from '../../partner/domain'
const db=useDb(),session=useSession(),message=ref('')
const matters=computed(()=>db.data.legalMatters.filter(matter=>matter.firmOrgId===session.activePersona?.orgId))
function advance(id:string,stage:'preparing'|'signing_scheduled'|'executed'|'completed'){const matter=db.data.legalMatters.find(item=>item.id===id);if(!matter)return;try{addLegalMilestone(id,stage,matter.version);message.value=`Matter moved to ${stage}.`}catch(e){message.value=e instanceof Error?e.message:''}}
</script>
<template><div class="page"><header class="page-header"><div><p class="eyebrow">Legal partner portal</p><h1>My matters</h1><p>Sale and loan matters remain separate, with source-dated service clocks.</p></div><StatusBadge :label="session.activePersona?.orgId||'Firm'"/></header><PreviewBanner/><p class="preview-banner">TO CONFIRM · Working hours, timezone and state-holiday calendar before live timers.</p><p v-if="message" class="card">{{message}}</p><article v-for="matter in matters" :key="matter.id" class="card"><div class="actions" style="justify-content:space-between"><h2>{{matter.kind==='sale'?'SALE':'LOAN'}} · {{matter.id}}</h2><StatusBadge :label="matter.stage"/></div><div class="card-grid"><article><span class="source-meta">Instruction issued</span><strong>{{matter.clock.instructionIssuedAt||'Unknown'}}</strong></article><article><span class="source-meta">Delivered</span><strong>{{matter.clock.deliveredAt||'Unknown'}}</strong></article><article><span class="source-meta">Acknowledged</span><strong>{{matter.clock.acknowledgedAt||'Unknown'}}</strong></article><article><span class="source-meta">Package ready</span><strong>{{matter.clock.packageReadyAt||'Unknown'}}</strong></article><article><span class="source-meta">Appointment</span><strong>{{matter.clock.appointmentAt||'Unknown'}}</strong></article><article><span class="source-meta">Executed</span><strong>{{matter.clock.executedAt||'Unknown'}}</strong></article></div><p>Business hours since delivery: {{matter.clock.deliveredAt?businessHoursBetween(matter.clock.deliveredAt,db.data.meta.now):'Unknown'}}</p><div class="actions"><el-button @click="advance(matter.id,'preparing')">Prepare</el-button><el-button @click="advance(matter.id,'signing_scheduled')">Schedule signing</el-button><el-button @click="advance(matter.id,'executed')">Record execution</el-button><el-button @click="advance(matter.id,'completed')">Complete</el-button><router-link to="/documents">Documents</router-link></div></article></div></template>
